dict(idx=43, hab="E4", n=3,
     stem="Uma prefeitura vai construir três postos de saúde, $P_1$, $P_2$ e $P_3$, equidistantes entre si (10 km um do outro), de forma que as distâncias dos três postos ao hospital H sejam iguais. Os quatro pontos estão no mesmo plano.\n\nA distância, em quilômetro, entre o hospital e cada posto está entre",
     erros={"A":"Usou um terço da altura (o apótema).","B":"Usou metade do lado (5).","D":"Usou a altura do triângulo (≈ 8,66) arredondando para baixo.","E":"Usou a altura do triângulo (≈ 8,66)."},
     res="H é o centro do triângulo equilátero de lado 10. Distância = 2/3 da altura = (2/3)·5√3 = 10/√3 ≈ 5,77."),
